export const CYBERBULLYING_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): apa itu perundungan siber
{n:1,type:"mcq",micro:"Apa itu perundungan siber",q:"'Perundungan siber' (cyberbullying) adalah...",options:["Tindakan menyakiti, mengejek, atau mengucilkan seseorang berulang kali lewat perangkat digital/internet","Bercanda sekali dengan teman dekat yang sama-sama tertawa","Memberi kritik yang membangun pada karya seseorang"],answer:0,explain:"Kata kuncinya: menyakiti, dengan sengaja, berulang, & ada ketidakseimbangan kekuatan (mis. banyak vs satu orang).",hint:"Menyakiti berulang lewat digital, atau bercanda bersama / kritik membangun?"},
{n:2,type:"mcq",micro:"Bentuk-bentuk perundungan siber",q:"Perundungan siber bisa berbentuk...",options:["Hanya terjadi lewat panggilan telepon","Mengejek di komentar, menyebarkan rumor, mengucilkan dari grup, atau menyamar jadi orang lain untuk mempermalukan","Hanya berupa kata-kata kasar langsung"],answer:1,explain:"Bentuknya beragam: kata-kata, gambar, pengucilan sosial, penyamaran identitas, semua bisa jadi alat perundungan.",hint:"Beragam bentuk (ejek, rumor, ucilkan, samaran), atau hanya kata kasar langsung?"},
{n:3,type:"mcq",micro:"Beda bercanda & perundungan",q:"Perbedaan utama antara bercanda yang sehat & perundungan:",options:["Bercanda selalu dilakukan sekali, perundungan berkali-kali","Tidak ada bedanya sama sekali","Bercanda sehat membuat SEMUA pihak (termasuk yang jadi objek) sama-sama nyaman & tertawa; perundungan menyakiti satu pihak yang tidak berdaya membela diri"],answer:2,explain:"Kalau salah satu pihak merasa terluka & tidak nyaman meski yang lain menganggapnya 'cuma bercanda', itu bukan lagi bercanda yang sehat.",hint:"Semua pihak nyaman vs satu pihak terluka, atau tidak ada beda?"},
{n:4,type:"mcq",micro:"Berulang & sengaja",q:"Ciri yang membedakan perundungan dari konflik biasa satu kali:",options:["Terjadi berulang & disengaja untuk menyakiti, bukan kesalahpahaman satu kali yang bisa diselesaikan","Selalu melibatkan lebih dari 5 orang","Selalu terjadi lewat video, bukan teks"],answer:0,explain:"Pertengkaran sesekali antar teman berbeda dari pola yang berulang & sengaja menyakiti seseorang.",hint:"Berulang & disengaja, atau soal jumlah orang / jenis media?"},
{n:5,type:"mcq",micro:"Perundungan siber tidak berhenti di layar",q:"Kenapa perundungan siber bisa terasa lebih berat dibanding perundungan tatap muka bagi sebagian korban?",options:["Tidak pernah memengaruhi perasaan seseorang","Bisa terjadi 24 jam, mengikuti korban ke rumah lewat HP, & sulit dihindari meski sudah pulang sekolah","Selalu lebih ringan karena tidak bertemu langsung"],answer:1,explain:"Perundungan tatap muka biasanya berhenti saat pulang sekolah; perundungan siber bisa terus mengejar lewat notifikasi, kapan saja.",hint:"Bisa terus mengejar 24 jam, atau selalu lebih ringan?"},
{n:6,type:"mcq",micro:"Menyebar rumor/gosip",q:"Menyebarkan cerita/gosip yang menyakitkan tentang seseorang (benar atau salah) lewat pesan/media sosial adalah bentuk...",options:["Cara sah menyampaikan kebenaran","Tidak berbahaya selama sebagian ceritanya benar","Perundungan siber lewat penyebaran informasi yang merugikan"],answer:2,explain:"Menyebarkan sesuatu yang menyakitkan tentang seseorang, apa pun kebenarannya, tetap bisa merugikan & termasuk perundungan.",hint:"Bentuk perundungan, atau cara sah / tidak berbahaya?"},
{n:7,type:"mcq",micro:"Pengucilan sosial digital",q:"Sengaja mengeluarkan seseorang dari grup chat atau tidak mengajaknya ikut kegiatan daring, berulang & disengaja untuk menyakiti, adalah...",options:["Bentuk perundungan siber lewat pengucilan, meski tidak ada kata kasar apa pun","Bukan perundungan karena tidak ada kata-kata jahat","Hal yang wajar terjadi di pertemanan"],answer:0,explain:"Perundungan tidak selalu berupa kata-kata; pengucilan yang disengaja & menyakitkan juga termasuk bentuknya.",hint:"Termasuk perundungan meski tanpa kata kasar, atau bukan / wajar?"},
{n:8,type:"mcq",micro:"Menyamar jadi orang lain",q:"Membuat akun palsu meniru identitas seseorang untuk mempermalukan atau menipu orang lain atas namanya adalah...",options:["Cara sah untuk 'bercanda'","Bentuk perundungan siber yang serius, disebut peniruan identitas (impersonation)","Hal yang lucu & tidak berbahaya"],answer:1,explain:"Meniru identitas seseorang untuk merugikannya adalah pelanggaran serius, bisa merusak reputasi orang tersebut.",hint:"Bentuk perundungan serius, atau lucu & tidak berbahaya?"},
{n:9,type:"order",micro:"Mengenali pola perundungan",q:"Urutkan tanda yang menunjukkan sesuatu sudah menjadi perundungan, bukan sekadar konflik biasa.",items:["Sesuatu terjadi yang menyakiti perasaan seseorang","Kejadian itu terulang lagi & lagi dengan pola yang sama","Orang yang menyakiti terus melakukannya meski tahu itu menyakiti","Korban merasa tidak berdaya membela diri karena ketidakseimbangan kekuatan"],answer:[0,1,2,3],explain:"Sekali sakit hati ≠ perundungan. Pola berulang + sengaja + ketidakseimbangan kekuatan adalah ciri khas perundungan.",hint:"Ketidakseimbangan kekuatan biasanya muncul di awal atau menjadi ciri yang menetap setelah pola berulang?"},
{n:10,type:"mcq",micro:"Perundungan bisa terjadi di mana saja daring",q:"Perundungan siber bisa terjadi di...",options:["Hanya di satu platform tertentu yang terkenal","Hanya lewat email","Media sosial, grup chat, game daring, komentar video, & platform apa pun yang memungkinkan interaksi"],answer:2,explain:"Di mana pun orang bisa berinteraksi secara daring, perundungan berpotensi terjadi, termasuk dalam game bersama.",hint:"Bisa di berbagai platform, atau hanya satu tempat tertentu?"},
{n:11,type:"tf",micro:"Perundungan siber sama seriusnya",q:"Benar atau Salah: Perundungan siber sama seriusnya dengan perundungan tatap muka & bisa berdampak besar pada perasaan seseorang, meski tidak melibatkan kontak fisik.",answer:true,explain:"Kata-kata & tindakan digital tetap punya dampak nyata pada perasaan & kesejahteraan seseorang, tidak 'lebih ringan' hanya karena lewat layar.",hint:"Sama seriusnya, atau lebih ringan karena tidak fisik?"},
{n:12,type:"tf",micro:"'Cuma bercanda' menghapus dampaknya?",q:"Benar atau Salah: Kalau pelaku bilang 'cuma bercanda', itu otomatis menghapus dampak menyakitkan yang dirasakan korban.",answer:false,explain:"Sebaliknya, niat pelaku tidak menghapus perasaan nyata korban. Kalau seseorang merasa terluka, itu tetap perlu diakui & ditangani, apa pun alasan pelakunya.",hint:"Menghapus dampak, atau dampaknya tetap nyata bagi korban?"},
{n:13,type:"mcq",micro:"Perundungan bisa terjadi antar teman dekat",q:"Perundungan siber bisa terjadi bahkan antara orang yang tadinya berteman, karena...",options:["Hubungan bisa berubah & dinamika kekuasaan (mis. popularitas, informasi pribadi yang diketahui) bisa disalahgunakan","Teman tidak mungkin saling menyakiti secara digital","Hanya terjadi antara orang asing"],answer:0,explain:"Kadang justru mantan teman dekat yang tahu kelemahan/rahasia seseorang & bisa memanfaatkannya untuk menyakiti.",hint:"Bisa terjadi antar teman dekat juga, atau tidak mungkin / hanya orang asing?"},
{n:14,type:"mcq",micro:"Doxing ringan",q:"Membagikan info pribadi seseorang (alamat, nomor HP, jadwal) tanpa izin dengan maksud membuat mereka merasa terancam atau dipermalukan adalah...",options:["Tidak berbahaya selama infonya benar","Bentuk perundungan/pelecehan yang serius, disebut 'doxing'","Cara sah menyebarkan info publik"],answer:1,explain:"Membagikan info pribadi dengan niat merugikan adalah pelanggaran serius yang bisa membahayakan keselamatan seseorang.",hint:"Bentuk pelanggaran serius, atau cara sah karena infonya benar?"},
{n:15,type:"mcq",micro:"Perundungan lewat gambar/meme",q:"Membuat & menyebarkan meme yang mengejek penampilan/kekurangan seseorang secara berulang adalah...",options:["Selalu aman selama dibuat dengan kreatif","Bukan perundungan karena berupa gambar, bukan kata-kata","Bentuk perundungan siber lewat gambar, meski dikemas sebagai 'lucu'"],answer:2,explain:"Format 'lucu' tidak menghapus dampak menyakitkannya. Meme yang menyerang seseorang secara pribadi tetap perundungan.",hint:"Tetap perundungan meski 'lucu', atau aman / bukan perundungan karena gambar?"},
{n:16,type:"tf",micro:"Semua orang bisa jadi korban",q:"Benar atau Salah: Hanya orang yang terlihat lemah atau tidak populer yang bisa menjadi korban perundungan siber; orang yang populer & percaya diri kebal darinya.",answer:false,explain:"Sebaliknya, siapa pun bisa menjadi korban perundungan siber. Tidak ada yang 'kebal' hanya karena terlihat kuat atau populer.",hint:"Siapa pun bisa jadi korban, atau hanya yang lemah/tidak populer?"},
{n:17,type:"mcq",micro:"Kesengajaan menyakiti berulang",q:"Elemen kunci yang membedakan perundungan dari kesalahan sekali yang tidak disengaja:",options:["Kesengajaan untuk menyakiti & pengulangan, bukan satu kejadian tak sengaja yang lalu diperbaiki","Jumlah kata yang dipakai","Waktu terjadinya (siang vs malam)"],answer:0,explain:"Satu kali salah ucap yang lalu diakui & diperbaiki berbeda dari pola yang sengaja diulang untuk menyakiti.",hint:"Kesengajaan & pengulangan, atau jumlah kata / waktu kejadian?"},
{n:18,type:"mcq",micro:"Perundungan tidak selalu terlihat",q:"Perundungan siber bisa terjadi diam-diam lewat pesan pribadi yang tidak dilihat orang lain. Ini artinya...",options:["Hanya perundungan publik yang perlu ditangani","Orang di sekitar (teman, keluarga) mungkin tidak menyadarinya sampai korban bercerita atau tanda-tandanya terlihat","Perundungan yang tidak terlihat berarti tidak nyata"],answer:1,explain:"Karena bisa tersembunyi di pesan pribadi, penting bagi orang dewasa & teman untuk peka pada perubahan perilaku, bukan hanya menunggu bukti publik.",hint:"Bisa tidak disadari orang sekitar, atau berarti tidak nyata?"},
{n:19,type:"mcq",micro:"Perundungan & kekuasaan yang tidak seimbang",q:"'Ketidakseimbangan kekuasaan' dalam perundungan bisa berarti...",options:["Pelaku selalu lebih tinggi badannya","Pelaku selalu lebih tua usianya","Pelaku punya lebih banyak pengikut, pengaruh sosial, atau informasi untuk merugikan korban yang sulit membela diri setara"],answer:2,explain:"Ketidakseimbangan bisa berupa popularitas, jumlah orang yang ikut menyerang, atau info yang dipakai mengancam, bukan sekadar fisik.",hint:"Popularitas/pengaruh/info, atau selalu soal fisik/usia?"},
{n:20,type:"open",micro:"Bedakan konflik biasa & perundungan",q:"Bandingkan dua situasi: (1) Dua teman bertengkar sekali lewat chat karena salah paham soal janji, lalu saling minta maaf & baikan. (2) Sekelompok siswa terus-menerus mengirim pesan mengejek penampilan satu siswa selama berminggu-minggu di grup kelas, meski siswa itu sudah memohon berhenti. Jelaskan: (a) kenapa situasi 1 BUKAN perundungan, (b) kenapa situasi 2 ADALAH perundungan, (c) 3 ciri kunci yang kamu pakai untuk membedakan keduanya.",sample:"(a) Situasi 1 bukan perundungan karena: ini kejadian satu kali (bukan pola berulang), berawal dari kesalahpahaman yang wajar terjadi dalam pertemanan (bukan niat sengaja menyakiti), & diselesaikan dengan permintaan maaf dari kedua pihak, menunjukkan hubungan yang setara & bisa saling memperbaiki. (b) Situasi 2 adalah perundungan karena: terjadi berulang selama berminggu-minggu (pola, bukan sekali), sengaja menyerang penampilan pribadi seseorang (bukan kesalahpahaman), melibatkan kelompok melawan satu orang (ketidakseimbangan kekuatan), & terus berlanjut meski korban sudah jelas-jelas meminta berhenti (menunjukkan pelaku tahu itu menyakiti tapi tetap melanjutkan). (c) Tiga ciri kunci pembeda: (1) Berulang vs sekali terjadi. (2) Disengaja untuk menyakiti vs kesalahpahaman yang wajar. (3) Ketidakseimbangan kekuatan (kelompok vs individu, atau pihak yang jelas lebih berkuasa) vs hubungan yang setara antara dua pihak yang sama-sama bisa membela diri & memperbaiki.",explain:"Jawaban baik: penjelasan yang jelas untuk kedua situasi berdasarkan ciri konkret (berulang, kesengajaan, ketidakseimbangan kekuatan), bukan hanya 'situasi 2 lebih jahat'. Tiga ciri kunci harus sama dengan yang dipakai menjelaskan (a) & (b), menunjukkan pemahaman yang konsisten.",hint:"Fokus pada TIGA hal: apakah berulang, apakah disengaja untuk menyakiti, & apakah ada ketidakseimbangan kekuatan antara pihak yang terlibat."},

// FASE B — PEMAHAMAN (21-40): dampak, bystander, empati
{n:21,type:"classify",micro:"Perundungan vs bukan perundungan",q:"Kelompokkan tiap situasi ke 'Perundungan siber' atau 'Bukan perundungan'.",items:["Terus mengirim pesan mengejek berat badan seseorang meski sudah diminta berhenti","Memberi kritik jujur tapi sopan tentang sebuah karya, sekali, dengan niat membantu","Sengaja membuat grup baru tanpa mengundang satu orang tertentu berulang kali untuk mengucilkannya","Berdebat sekali soal pendapat berbeda lalu sama-sama move on"],groups:["Perundungan siber","Bukan perundungan"],answer:{"Perundungan siber":["Terus mengirim pesan mengejek berat badan seseorang meski sudah diminta berhenti","Sengaja membuat grup baru tanpa mengundang satu orang tertentu berulang kali untuk mengucilkannya"],"Bukan perundungan":["Memberi kritik jujur tapi sopan tentang sebuah karya, sekali, dengan niat membantu","Berdebat sekali soal pendapat berbeda lalu sama-sama move on"],},explain:"Perundungan: berulang, sengaja menyakiti, meski diminta berhenti. Bukan perundungan: sekali, niat membantu, bisa diselesaikan.",hint:"Berulang & sengaja menyakiti, atau sekali & bisa diselesaikan?"},
{n:22,type:"mcq",micro:"Dampak emosional",q:"Perundungan siber bisa memengaruhi korban secara emosional seperti...",options:["Rasa cemas, sedih, malu, atau kehilangan percaya diri, yang bisa bertahan lama","Tidak berpengaruh apa-apa pada perasaan","Selalu membuat korban lebih kuat tanpa efek buruk"],answer:0,explain:"Dampak emosional ini nyata & penting diakui, bukan hal yang harus 'dianggap enteng' atau 'dihadapi sendiri'.",hint:"Berdampak nyata pada perasaan, atau tidak berpengaruh / selalu memperkuat?"},
{n:23,type:"mcq",micro:"Bystander (penonton) & upstander (pembela)",q:"Beda 'bystander' & 'upstander' saat menyaksikan perundungan:",options:["Bystander selalu ikut menyerang korban","Bystander hanya menonton/diam; upstander berani membantu dengan cara yang aman (melapor, mendukung korban, dll)","Keduanya sama saja"],answer:1,explain:"Menjadi upstander tidak selalu berarti melawan langsung, bisa juga melapor ke orang dewasa atau mendukung korban secara pribadi.",hint:"Diam vs membantu dengan aman, atau keduanya sama?"},
{n:24,type:"mcq",micro:"Kenapa penonton sering diam",q:"Alasan umum orang memilih diam saat melihat perundungan (efek bystander):",options:["Karena mereka tidak peduli sama sekali pada siapa pun","Karena perundungan yang mereka lihat tidak nyata","Takut jadi sasaran berikutnya, bingung harus berbuat apa, atau berpikir 'pasti ada orang lain yang bertindak'"],answer:2,explain:"Memahami alasan ini (tanpa membenarkannya) membantu kita menyiapkan diri untuk bertindak meski merasa takut atau ragu.",hint:"Takut/bingung/berpikir orang lain akan bertindak, atau tidak peduli / tidak nyata?"},
{n:25,type:"mcq",micro:"Dampak pada pelaku juga",q:"Selain korban, perundungan siber juga bisa berdampak pada pelaku karena...",options:["Bisa menghadapi konsekuensi (dilaporkan, dikeluarkan dari platform, masalah dengan sekolah/hukum) & merusak hubungan mereka sendiri","Pelaku tidak pernah menghadapi konsekuensi apa pun","Perundungan selalu menguntungkan pelaku tanpa risiko"],answer:0,explain:"Perundungan bukan tanpa risiko bagi pelaku. Banyak platform & sekolah menindak tegas, & hubungan sosial pelaku juga bisa rusak.",hint:"Ada konsekuensi bagi pelaku, atau tidak pernah / selalu untung?"},
{n:26,type:"mcq",micro:"Perundungan & tekanan kelompok",q:"Seseorang ikut mengejek karena teman-temannya melakukannya, meski sebenarnya merasa tidak enak. Ini menunjukkan...",options:["Tekanan kelompok tidak pernah memengaruhi perilaku","Tekanan kelompok bisa membuat orang ikut serta dalam perundungan meski hati kecilnya tidak setuju","Orang itu pasti memang jahat dari dasarnya"],answer:1,explain:"Menyadari kekuatan tekanan kelompok membantu kita mengenali & menahan diri saat merasakannya sendiri.",hint:"Tekanan kelompok bisa membuat ikut serta, atau pasti jahat dari dasarnya?"},
{n:27,type:"tf",micro:"Diam bisa memperkuat perundungan",q:"Benar atau Salah: Banyaknya orang yang menonton perundungan tanpa bertindak apa pun tidak berpengaruh sama sekali pada perilaku pelaku.",answer:false,explain:"Sebaliknya, kesunyian penonton bisa dibaca pelaku sebagai persetujuan diam-diam, membuatnya makin percaya diri melanjutkan, meski sebenarnya banyak yang tidak setuju di hati mereka.",hint:"Bisa memperkuat perundungan, atau tidak berpengaruh?"},
{n:28,type:"tf",micro:"Membela korban selalu berarti melawan langsung",q:"Benar atau Salah: Menjadi 'upstander' HARUS selalu berarti membalas pelaku secara terbuka & langsung; tidak ada cara lain yang dianggap membantu.",answer:false,explain:"Sebaliknya, ada banyak cara membantu dengan aman: melapor ke orang dewasa, mendukung korban secara pribadi, tidak ikut menyebarkan, atau mengajak korban bicara. Konfrontasi langsung bukan satu-satunya cara & kadang bukan yang teraman.",hint:"Harus selalu melawan langsung, atau ada banyak cara aman lain?"},
{n:29,type:"mcq",micro:"Perundungan & rasa aman di rumah",q:"Kenapa perundungan siber bisa mengganggu rasa aman seseorang bahkan di rumah sendiri?",options:["Karena perundungan siber selalu berhenti begitu sampai di rumah","Rumah selalu terpisah sepenuhnya dari dunia digital","Karena HP/perangkat bisa membawa pesan menyakitkan masuk ke ruang yang biasanya terasa aman, kapan pun"],answer:2,explain:"Ini salah satu alasan perundungan siber bisa terasa lebih berat: tidak ada 'tempat aman' yang benar-benar terpisah dari layar.",hint:"Membawa pesan menyakitkan masuk ke rumah kapan pun, atau selalu berhenti di rumah?"},
{n:30,type:"order",micro:"Langkah menjadi upstander yang aman",q:"Urutkan langkah menjadi upstander (pembela) yang aman saat melihat perundungan terjadi.",items:["Nilai situasi: apakah aman untuk bertindak langsung atau lebih baik lewat orang dewasa","Dukung korban secara pribadi (pesan langsung, tanya keadaan) agar ia merasa tidak sendirian","Jangan ikut menyebarkan atau menyukai konten yang merundung","Laporkan ke orang dewasa/platform bila situasinya serius atau berlanjut"],answer:[0,1,2,3],explain:"Nilai keamanan dulu → dukung korban secara pribadi → jangan ikut sebar → laporkan bila perlu. Keamanan diri sendiri & korban dipikirkan sejak awal.",hint:"Menilai keamanan situasi dilakukan sebelum atau sesudah mendukung korban secara pribadi?"},
{n:31,type:"mcq",micro:"Perundungan & harga diri",q:"Perundungan siber yang berlangsung lama bisa memengaruhi bagaimana seseorang memandang dirinya sendiri karena...",options:["Pesan negatif yang berulang bisa mulai dipercaya sebagai 'kebenaran' tentang diri sendiri, meski itu tidak benar","Kata-kata orang lain tidak pernah memengaruhi cara pandang diri","Hanya memengaruhi orang yang memang sudah tidak percaya diri sejak awal"],answer:0,explain:"Pengulangan bisa membuat pesan negatif terasa 'benar', meski sebenarnya itu hanyalah perkataan pelaku, bukan kebenaran tentang siapa korban sebenarnya.",hint:"Bisa mulai dipercaya meski tidak benar, atau tidak pernah memengaruhi?"},
{n:32,type:"tf",micro:"Perundungan bisa dilaporkan meski anonim",q:"Benar atau Salah: Kalau pelaku memakai akun anonim/palsu, korban tidak bisa melakukan apa-apa lagi, laporan jadi percuma.",answer:false,explain:"Sebaliknya, anonimitas pelaku tidak menghilangkan hak korban untuk melapor & mendapat bantuan. Platform & orang dewasa tetap bisa membantu meski identitas pelaku belum jelas.",hint:"Tetap bisa dilaporkan meski anonim, atau tidak bisa dilakukan apa-apa?"},
{n:33,type:"mcq",micro:"Perundungan menyasar identitas",q:"Perundungan yang menyerang identitas seseorang (suku, agama, penampilan fisik, kondisi keluarga) sering terasa lebih berat karena...",options:["Tidak berhubungan dengan perasaan seseorang","Menyerang sesuatu yang tidak bisa (atau sulit) diubah tentang diri seseorang, terasa sebagai penolakan pada keberadaannya","Selalu lebih ringan karena tidak menyangkut perilaku"],answer:1,explain:"Menyerang hal yang melekat pada identitas seseorang berbeda dampaknya dari mengomentari perilaku yang bisa diubah.",hint:"Menyerang hal yang tak bisa diubah terasa lebih berat, atau selalu lebih ringan?"},
{n:34,type:"mcq",micro:"Perundungan & rasa malu melapor",q:"Korban sering enggan bercerita/melapor karena rasa malu atau takut disalahkan. Cara membantu mereka lebih berani bercerita:",options:["Memaksa mereka bercerita di depan banyak orang","Menyalahkan mereka karena 'kenapa baru cerita sekarang'","Ciptakan suasana yang tidak menghakimi, dengarkan dulu tanpa menyalahkan, & yakinkan bahwa ini bukan salah mereka"],answer:2,explain:"Rasa aman untuk bercerita dibangun dari respons yang tidak menghakimi. Menyalahkan korban hanya menambah beban.",hint:"Ciptakan suasana aman & tidak menghakimi, atau paksa / salahkan?"},
{n:35,type:"mcq",micro:"Perundungan bisa dimulai dari kesalahpahaman kecil",q:"Kadang perundungan berawal dari sesuatu yang kecil (candaan yang keterusan, kesalahpahaman yang tidak pernah diluruskan). Ini menunjukkan pentingnya...",options:["Menghentikan pola yang menyakitkan sedini mungkin, sebelum berkembang jadi pola yang lebih besar & sulit dihentikan","Membiarkan saja karena awalnya kecil pasti tidak berbahaya","Menunggu sampai jadi sangat parah baru bertindak"],answer:0,explain:"Menangani tanda awal (sebelum menjadi pola berulang yang mengakar) lebih mudah daripada menunggu situasinya memburuk.",hint:"Hentikan sedini mungkin, atau biarkan / tunggu sampai parah?"},
{n:36,type:"mcq",micro:"Perundungan & kelompok yang berubah jadi 'gerombolan'",q:"Fenomena di mana banyak orang ikut menyerang satu orang secara daring (dogpiling/gerombolan) sering terjadi karena...",options:["Tidak pernah terjadi di dunia nyata media sosial","Merasa 'aman' karena banyak orang lain juga melakukannya, tanggung jawab terasa terbagi & berkurang untuk masing-masing individu","Setiap orang secara individu berpikir sangat matang sebelum ikut serta"],answer:1,explain:"'Difusi tanggung jawab', merasa tidak sepenuhnya bertanggung jawab karena banyak yang ikut, adalah salah satu alasan orang mudah ikut serta tanpa berpikir panjang.",hint:"Merasa aman & tanggung jawab terbagi, atau berpikir matang sebelum ikut?"},
{n:37,type:"tf",micro:"Menonton tanpa ikut menulis tetap berdampak",q:"Benar atau Salah: Menyukai (like) atau membagikan konten yang merundung seseorang tidak berpengaruh sama sekali selama kamu tidak menulis komentar jahat sendiri.",answer:false,explain:"Sebaliknya, interaksi apa pun (like, share, tonton berulang) menambah visibilitas & bisa memperkuat dampak buruknya pada korban, meski tidak menulis komentar sendiri.",hint:"Tetap berdampak meski tidak menulis komentar, atau tidak berpengaruh sama sekali?"},
{n:38,type:"mcq",micro:"Perundungan & pengaruh pada persahabatan",q:"Perundungan siber di dalam sebuah lingkaran pertemanan bisa merusak...",options:["Hanya merusak hubungan pelaku & korban, tidak memengaruhi yang lain","Selalu memperkuat pertemanan yang tersisa","Kepercayaan dalam kelompok itu sendiri, membuat anggota lain juga merasa tidak aman"],answer:2,explain:"Melihat teman menyerang teman lain bisa membuat semua anggota kelompok merasa tidak aman, khawatir jadi sasaran berikutnya.",hint:"Merusak kepercayaan seluruh kelompok, atau hanya pelaku-korban / memperkuat?"},
{n:39,type:"mcq",micro:"Empati sebagai pencegahan",q:"Membiasakan diri bertanya 'bagaimana perasaanku kalau ini terjadi padaku?' sebelum mengirim sesuatu adalah bentuk...",options:["Empati praktis yang bisa mencegah kita tanpa sadar ikut menyakiti orang lain","Kebiasaan yang tidak berguna","Hanya perlu dipikirkan orang dewasa"],answer:0,explain:"Empati sederhana ini adalah alat pencegahan yang kuat, membuat kita berpikir dua kali sebelum bertindak.",hint:"Bentuk empati pencegahan, atau tidak berguna?"},
{n:40,type:"open",micro:"Analisis dinamika kelompok",q:"Di sebuah grup kelas, satu siswa mulai mengejek siswa lain, lalu beberapa teman ikut menambahkan ejekan karena 'seru & ramai'. Sebagian besar anggota grup diam saja, meski beberapa merasa tidak nyaman. Analisis: (a) kenapa yang lain ikut menambahkan ejekan meski awalnya bukan ide mereka, (b) kenapa yang merasa tidak nyaman tetap memilih diam, (c) 3 hal konkret yang bisa dilakukan salah satu anggota diam itu untuk membantu tanpa membahayakan dirinya sendiri.",sample:"(a) Yang lain ikut karena tekanan kelompok & rasa 'aman berjumlah', ikut menambahkan ejekan terasa lebih mudah & menyenangkan saat sudah banyak yang melakukannya, & tanggung jawab individu terasa 'terbagi' karena banyak yang terlibat sehingga masing-masing merasa 'bukan cuma aku'. (b) Yang merasa tidak nyaman diam karena takut jadi sasaran berikutnya kalau membela korban, bingung harus berkata apa tanpa terlihat aneh, atau berpikir 'nanti juga ada yang menghentikan, bukan tugasku'. (c) Tiga hal yang bisa dilakukan tanpa membahayakan diri: (1) Kirim pesan pribadi ke korban setelahnya, seperti 'aku lihat tadi, itu nggak oke, kamu nggak sendirian' untuk menunjukkan dukungan tanpa konfrontasi terbuka. (2) Tidak ikut menambahkan komentar atau memberi reaksi (like/emoji tertawa) pada ejekan tersebut, meski tidak menegur langsung, setidaknya tidak menambah bahan bakarnya. (3) Beri tahu guru/wali kelas secara pribadi tentang apa yang terjadi di grup, supaya ada orang dewasa yang bisa menangani situasinya secara resmi tanpa dia harus menghadapi kelompok itu sendirian.",explain:"Jawaban baik: penjelasan yang menunjukkan pemahaman tentang tekanan kelompok & difusi tanggung jawab untuk (a) & (b) (bukan sekadar 'karena mereka jahat/takut'), & 3 langkah konkret di (c) yang benar-benar aman & bisa dilakukan tanpa perlu konfrontasi terbuka yang berisiko.",hint:"Bagian (c) harus benar-benar AMAN, hindari saran yang mengharuskan si anggota 'melawan' terbuka di depan kelompok yang bisa membuatnya jadi sasaran berikutnya."},

// FASE C — PENERAPAN (41-60): apa yang dilakukan (korban, upstander)
{n:41,type:"mcq",micro:"Langkah pertama bila jadi korban",q:"Kalau kamu mengalami perundungan siber, langkah pertama yang aman:",options:["Diam & menyimpannya sendiri tanpa bercerita ke siapa pun","Jangan balas dengan kekerasan/ejekan serupa; simpan bukti (tangkapan layar) & beri tahu orang dewasa tepercaya","Membalas dengan ejekan yang sama untuk 'membalas'"],answer:1,explain:"Membalas sering memperburuk situasi. Menyimpan bukti & bercerita ke orang dewasa membuka jalan penanganan yang tepat.",hint:"Simpan bukti & beri tahu dewasa, atau balas / diam sendiri?"},
{n:42,type:"mcq",micro:"Kenapa jangan membalas",q:"Kenapa membalas perundungan dengan cara yang sama (ejekan balik) biasanya bukan pilihan yang baik?",options:["Membalas selalu menyelesaikan masalah dengan cepat","Membalas tidak pernah punya konsekuensi apa pun","Bisa memperburuk situasi, membuatmu terlihat sama-sama bersalah, & tidak menghentikan pola yang menyakitkan"],answer:2,explain:"Perang balas-membalas jarang menyelesaikan akar masalah & bisa membuat situasi tampak seperti 'pertengkaran dua pihak', bukan perundungan sepihak.",hint:"Memperburuk & tidak menyelesaikan, atau selalu efektif menyelesaikan?"},
{n:43,type:"mcq",micro:"Menyimpan bukti",q:"Cara menyimpan bukti perundungan yang berguna untuk laporan:",options:["Tangkapan layar yang menunjukkan siapa mengirim, kapan, & isi pesannya, disimpan di tempat yang aman","Menghapus semuanya secepat mungkin agar tidak melihatnya lagi","Membagikan buktinya ke banyak orang untuk 'mempermalukan balik'"],answer:0,explain:"Bukti yang lengkap & tersimpan membantu orang dewasa atau platform menindak dengan tepat. Menyebarkannya sendiri bisa memperburuk keadaan.",hint:"Simpan lengkap & aman, atau hapus semua / sebarkan sendiri?"},
{n:44,type:"mcq",micro:"Memblokir pelaku",q:"Memblokir akun pelaku perundungan adalah langkah yang...",options:["Hanya boleh dilakukan orang dewasa","Sah & seringkali membantu menghentikan kontak langsung, meski tidak selalu menyelesaikan seluruh masalah","Tanda kekalahan yang memalukan"],answer:1,explain:"Memblokir memutus akses langsung pelaku padamu. Ini alat perlindungan diri yang sah, bukan tanda kalah.",hint:"Langkah sah & membantu, atau tanda kalah / hanya untuk dewasa?"},
{n:45,type:"tf",micro:"Bercerita bukan tanda lemah",q:"Benar atau Salah: Bercerita ke orang dewasa tepercaya tentang perundungan yang dialami adalah tanda kelemahan yang sebaiknya dihindari.",answer:false,explain:"Sebaliknya, mencari bantuan saat dibutuhkan adalah kekuatan & langkah bijak, bukan kelemahan. Banyak masalah lebih mudah diatasi dengan bantuan orang lain.",hint:"Tanda berani & bijak, atau tanda lemah?"},
{n:46,type:"mcq",micro:"Memilih orang dewasa tepercaya",q:"Orang dewasa tepercaya untuk diajak bicara tentang perundungan bisa berupa...",options:["Harus selalu orang tua kandung, tidak ada pilihan lain","Tidak perlu orang dewasa, cukup diselesaikan sendiri","Orang tua/wali, guru, konselor sekolah, atau orang dewasa lain yang membuatmu merasa aman & didengar"],answer:2,explain:"Yang penting adalah orang yang membuatmu merasa aman bercerita & bisa membantu mengambil langkah, siapa pun itu.",hint:"Siapa pun yang membuat merasa aman, atau harus orang tua kandung / tak perlu siapa pun?"},
{n:47,type:"mcq",micro:"Melaporkan ke platform",q:"Kebanyakan platform media sosial/game punya fitur 'laporkan' (report) untuk konten/perilaku yang merundung. Melaporkannya berguna karena...",options:["Platform bisa menindak akun pelaku & mencegah perundungan berlanjut ke korban lain","Fitur laporan tidak pernah berfungsi","Hanya berguna untuk kasus yang sangat besar"],answer:0,explain:"Laporan yang jelas (dengan bukti) membantu platform bertindak, meski tidak selalu sempurna atau instan.",hint:"Membantu penindakan & mencegah korban lain, atau tak pernah berfungsi?"},
{n:48,type:"mcq",micro:"Tidak menyalahkan diri sendiri",q:"Korban perundungan sering (keliru) merasa itu 'salah mereka sendiri'. Kebenaran yang penting diingat:",options:["Selalu ada yang salah dari korban yang menyebabkan itu terjadi","Perundungan adalah pilihan & tanggung jawab pelaku, bukan kesalahan korban, apa pun alasan yang dipakai pelaku","Korban biasanya memang memancing perundungan"],answer:1,explain:"Menyalahkan korban ('kamu terlalu sensitif', 'kamu memancing') keliru & menambah beban. Tanggung jawab ada pada yang memilih menyakiti.",hint:"Tanggung jawab pelaku, bukan salah korban, atau korban biasanya memancing?"},
{n:49,type:"mcq",micro:"Menjaga jejak digital sendiri saat diserang",q:"Saat sedang mengalami perundungan, sebaiknya kamu juga tidak...",options:["Menyimpan bukti perundungan yang dialami","Bercerita ke orang tepercaya","Membalas dengan hal yang bisa dipakai sebagai 'bukti' bahwa kamu juga ikut menyerang, karena bisa membuat situasi tampak seperti pertengkaran dua arah"],answer:2,explain:"Menjaga responsmu sendiri tetap 'bersih' (tidak ikut menyerang balik) membuat situasi lebih jelas siapa yang sebenarnya melakukan perundungan.",hint:"Hindari ikut menyerang balik, atau hindari menyimpan bukti / bercerita?"},
{n:50,type:"order",micro:"Langkah menangani perundungan yang dialami",q:"Urutkan langkah menangani perundungan siber yang kamu alami.",items:["Jangan balas & simpan bukti (tangkapan layar) segera","Blokir pelaku bila memungkinkan untuk memutus kontak","Ceritakan ke orang dewasa tepercaya & tunjukkan buktinya","Laporkan ke platform bila perlu, & pertimbangkan langkah lanjutan bersama orang dewasa (mis. ke sekolah)"],answer:[0,1,2,3],explain:"Jangan balas + simpan bukti → blokir → ceritakan ke dewasa → laporkan & langkah lanjut. Bukti disimpan sebelum memblokir supaya tidak hilang.",hint:"Menyimpan bukti dilakukan sebelum atau sesudah memblokir pelaku?"},
{n:51,type:"mcq",micro:"Membantu teman yang jadi korban",q:"Kalau temanmu bercerita menjadi korban perundungan, respons pertama yang membantu:",options:["Dengarkan dengan sungguh-sungguh, jangan meremehkan ('ah cuma gitu doang'), & tanyakan apa yang bisa kamu bantu","Menyuruhnya 'jangan baper' & melupakannya saja","Langsung mengambil alih & membalas pelaku atas namanya tanpa bertanya dulu"],answer:0,explain:"Mendengarkan tanpa meremehkan membuat korban merasa didukung. Bertanya apa yang mereka butuhkan menghormati pilihan mereka.",hint:"Dengarkan & tanya bantuan apa, atau meremehkan / bertindak sendiri tanpa izin?"},
{n:52,type:"tf",micro:"Menegur pelaku secara langsung tidak selalu paling aman",q:"Benar atau Salah: Menegur pelaku perundungan secara langsung & terbuka selalu merupakan cara paling aman untuk membantu, dibanding melapor ke orang dewasa.",answer:false,explain:"Sebaliknya, tergantung situasi, kadang menegur langsung berisiko membuat diri sendiri jadi sasaran berikutnya. Melapor ke orang dewasa atau mendukung korban secara pribadi bisa jadi pilihan yang lebih aman.",hint:"Selalu paling aman, atau tergantung situasi & ada cara lain yang lebih aman?"},
{n:53,type:"mcq",micro:"Mendukung tanpa menghakimi cara korban bereaksi",q:"Kalau korban perundungan bereaksi dengan cara yang menurutmu 'berlebihan' (sangat marah/menangis), sikap yang tepat:",options:["Mengabaikan reaksinya karena dianggap berlebihan","Terima reaksi mereka sebagai wajar & sah bagi mereka, jangan menghakimi caranya merasakan sesuatu","Bilang mereka terlalu lebay & harus lebih tegar"],answer:1,explain:"Setiap orang punya cara berbeda merespons rasa sakit. Menghakimi reaksi mereka menambah beban, bukan membantu.",hint:"Terima reaksi mereka sebagai sah, atau menghakimi / abaikan?"},
{n:54,type:"mcq",micro:"Kapan melibatkan sekolah/pihak berwenang",q:"Perundungan siber yang melibatkan ancaman keselamatan, penyebaran info pribadi berbahaya, atau berlangsung sangat lama tanpa henti sebaiknya...",options:["Tetap diselesaikan sendiri tanpa melibatkan siapa pun","Diabaikan karena 'itu urusan anak-anak'","Dilaporkan ke sekolah atau pihak berwenang, tidak hanya diselesaikan sendiri antar siswa"],answer:2,explain:"Situasi yang serius atau berbahaya membutuhkan keterlibatan pihak yang punya wewenang untuk menangani secara resmi.",hint:"Libatkan sekolah/berwenang untuk kasus serius, atau selalu selesaikan sendiri / abaikan?"},
{n:55,type:"mcq",micro:"Menjaga diri sendiri saat membantu orang lain",q:"Saat membantu teman yang jadi korban, penting juga memperhatikan...",options:["Batasanmu sendiri; kamu boleh membantu tanpa harus menanggung semua beban sendirian, & bisa melibatkan orang dewasa","Kamu harus menyelesaikan semuanya sendirian tanpa bantuan siapa pun","Kepentinganmu sendiri tidak penting sama sekali saat membantu"],answer:0,explain:"Membantu dengan bijak berarti tahu kapan meminta bantuan tambahan, bukan menanggung beban sendirian sampai kewalahan.",hint:"Jaga batasan & libatkan bantuan, atau tanggung semua sendiri?"},
{n:56,type:"tf",micro:"Perundungan bisa dihentikan",q:"Benar atau Salah: Meski sulit, perundungan siber bisa dihentikan atau dikurangi lewat kombinasi tindakan (memblokir, melapor, dukungan orang dewasa/sekolah), bukan sesuatu yang harus 'dijalani' selamanya.",answer:true,explain:"Perundungan bukan takdir yang tidak bisa diubah. Langkah yang tepat & dukungan yang cukup bisa menghentikan atau menguranginya secara signifikan.",hint:"Bisa dihentikan/dikurangi, atau harus dijalani selamanya?"},
{n:57,type:"mcq",micro:"Merawat diri setelah mengalami perundungan",q:"Selain menangani masalahnya secara praktis (lapor, blokir), penting juga bagi korban untuk...",options:["Menjauhi semua orang & aktivitas yang disukai","Menghabiskan waktu dengan orang & aktivitas yang membuat mereka merasa dihargai & baik, tidak hanya fokus pada kejadian buruknya","Terus memikirkan kejadiannya berulang-ulang tanpa henti"],answer:1,explain:"Mengisi diri dengan hal & orang yang positif membantu memulihkan rasa percaya diri yang mungkin terguncang.",hint:"Isi dengan hal & orang positif, atau terus terpaku pada kejadian / menjauhi semua?"},
{n:58,type:"mcq",micro:"Menanggapi tekanan untuk ikut merundung",q:"Kalau teman-temanmu mengajakmu ikut mengejek seseorang secara daring, sikap yang berani:",options:["Ikut saja supaya tidak dijauhi","Diam & pura-pura tidak melihat ajakan itu","Menolak dengan sopan ('aku nggak mau ikutan ya') meski itu berarti tidak ikut arus kelompok"],answer:2,explain:"Menolak ikut serta, meski terasa berisiko secara sosial, adalah pilihan yang bertanggung jawab & bisa menghentikan penyebaran perundungan.",hint:"Menolak dengan sopan, atau ikut / diam pura-pura tak lihat?"},
{n:59,type:"mcq",micro:"Perundungan & kesabaran proses penyelesaian",q:"Setelah melapor, proses penanganan perundungan (oleh sekolah/platform) mungkin tidak instan. Sikap yang membantu:",options:["Bersabar sambil terus menjaga diri sendiri (dukungan orang dekat, aktivitas positif), & tetap update dengan orang dewasa yang membantu","Menyerah & menganggap tidak ada gunanya melapor","Mengambil tindakan sendiri yang berisiko karena merasa proses terlalu lambat"],answer:0,explain:"Proses resmi kadang butuh waktu, tapi itu tidak berarti sia-sia. Tetap terhubung dengan yang membantu & menjaga diri sendiri di tengah proses itu penting.",hint:"Bersabar & tetap jaga diri, atau menyerah / bertindak sendiri berisiko?"},
{n:60,type:"open",micro:"Rencana tindakan bila terjadi",q:"Buat 'rencana tindakan' pribadi untuk situasi bila kamu atau temanmu mengalami perundungan siber. Sertakan: (a) 3 langkah pertama yang akan kamu lakukan bila kamu sendiri jadi korban, (b) 3 langkah yang akan kamu lakukan bila melihat temanmu menjadi korban, (c) siapa orang dewasa tepercaya yang akan kamu hubungi & kenapa, (d) satu kalimat yang akan kamu ingat untuk menguatkan diri/temanmu di masa sulit itu.",sample:"(a) Bila aku jadi korban: (1) Tidak membalas dengan ejekan serupa, meski sangat ingin. (2) Segera menangkap layar semua bukti (pesan, komentar, nama akun) sebelum diblokir/dihapus pelaku. (3) Cerita ke orang tuaku malam itu juga, tunjukkan buktinya, & minta bantuan memikirkan langkah selanjutnya bersama. (b) Bila temanku jadi korban: (1) Dengarkan ceritanya tanpa meremehkan atau menyalahkan dia. (2) Tanya apa yang dia butuhkan, apakah ingin aku menemani lapor ke guru, atau cukup didengarkan dulu. (3) Tidak ikut menyebarkan atau bereaksi (like/tertawa) pada konten yang merundungnya, & kalau situasinya serius, bantu dia (dengan izinnya) memberi tahu guru/orang dewasa. (c) Orang dewasa tepercaya: ibuku, karena aku selalu merasa didengar tanpa dihakimi saat cerita masalah padanya, & wali kelasku, karena dia dikenal serius menangani masalah antar siswa. (d) Kalimat penguat: 'Ini bukan salahku/salahmu, ini pilihan orang yang memilih menyakiti, & aku/kamu tidak sendirian menghadapinya.'",explain:"Jawaban baik: langkah (a) & (b) yang konkret & berbeda sesuai perannya (korban vs pendukung), penyebutan orang dewasa spesifik dengan alasan yang jujur (bukan generik), & kalimat penguat yang benar-benar menenangkan & menegaskan bahwa itu bukan kesalahan korban.",hint:"Bagian (c) sebaiknya menyebut orang SPESIFIK yang benar-benar kamu percaya, bukan kategori umum seperti 'orang tua' saja."},

// FASE D — PENALARAN (61-80): jadi pelaku tanpa sadar, batas, dukungan berkelanjutan
{n:61,type:"mcq",micro:"Bisa jadi pelaku tanpa sadar",q:"Seseorang bisa tanpa sadar ikut merundung ketika...",options:["Tidak mungkin terjadi tanpa niat jahat yang jelas","Ikut menertawakan/membagikan sesuatu yang menyakiti orang lain tanpa memikirkan dampaknya, meski tidak bermaksud jahat sejak awal","Selalu sadar & sengaja sejak awal niatnya jahat"],answer:1,explain:"Ikut serta 'ramai-ramai' atau menganggap sesuatu 'lucu' tanpa berpikir dampaknya bisa membuat seseorang ikut merundung tanpa sepenuhnya sadar.",hint:"Bisa terjadi tanpa sadar lewat ikut-ikutan, atau selalu sadar sejak awal?"},
{n:62,type:"mcq",micro:"Refleksi diri sebagai pencegahan",q:"Kalau kamu menyadari pernah ikut mengejek seseorang secara berlebihan tanpa berpikir panjang, sikap yang dewasa:",options:["Membela diri karena 'semua orang juga melakukannya'","Mengabaikan & berpura-pura tidak pernah terjadi","Akui, minta maaf dengan tulus, & berkomitmen berpikir lebih dulu sebelum bertindak ke depannya"],answer:2,explain:"Mengakui kesalahan & memperbaiki diri adalah tanda kematangan. Semua orang bisa khilaf; yang penting bagaimana meresponsnya.",hint:"Akui, minta maaf, & perbaiki, atau membela diri / abaikan?"},
{n:63,type:"mcq",micro:"Membedakan kritik sah & perundungan",q:"Kritik yang sah (mis. tentang karya/perilaku) berbeda dari perundungan karena kritik sah...",options:["Fokus pada hal spesifik yang bisa diperbaiki, disampaikan sekali dengan hormat, bukan menyerang pribadi berulang kali","Selalu terasa nyaman bagi yang dikritik","Tidak pernah membuat orang merasa tidak enak sama sekali"],answer:0,explain:"Kritik sah bisa terasa tidak nyaman tapi tetap fokus & konstruktif, berbeda dari serangan berulang yang menargetkan pribadi seseorang.",hint:"Fokus & konstruktif, sekali, hormat, atau selalu nyaman / tak pernah tak enak?"},
{n:64,type:"tf",micro:"Pelaku juga butuh dipahami (bukan dibenarkan)",q:"Benar atau Salah: Memahami kenapa seseorang melakukan perundungan (mis. karena dirundung juga, kesepian, cari perhatian) bisa membantu menanganinya, tapi TIDAK membenarkan tindakannya.",answer:true,explain:"Memahami akar penyebab bisa membantu pencegahan & penanganan yang lebih efektif, tanpa berarti perilakunya jadi bisa diterima.",hint:"Membantu memahami tanpa membenarkan, atau berarti tindakannya jadi boleh?"},
{n:65,type:"mcq",micro:"Perundungan sebagai siklus",q:"Kadang pelaku perundungan pernah menjadi korban perundungan sebelumnya. Ini penting dipahami karena...",options:["Tidak ada hubungan antara jadi korban & jadi pelaku","Menunjukkan pentingnya menangani semua pihak (bukan hanya menghukum) untuk memutus siklus yang bisa berulang","Berarti perundungan selalu dibenarkan sebagai 'balas dendam'"],answer:1,explain:"Memutus siklus (bukan hanya menghukum satu pihak) membantu mencegah perundungan berlanjut di masa depan.",hint:"Penting untuk memutus siklus, atau membenarkan balas dendam / tak ada hubungan?"},
{n:66,type:"mcq",micro:"Batas antara membela diri & membalas berlebihan",q:"Kalau kamu diserang, membela diri dengan menjelaskan fakta berbeda dari membalas dengan menyerang balik karena...",options:["Keduanya sama saja & sama efektifnya","Menyerang balik selalu lebih efektif menyelesaikan masalah","Membela diri fokus meluruskan/melindungi diri; membalas dengan menyerang justru menambah eskalasi & menyakiti balik"],answer:2,explain:"Membela diri secara tenang berbeda dari 'membalas dendam' yang justru bisa memperpanjang & memperparah konflik.",hint:"Membela diri vs menyerang balik, beda tujuan & dampak, atau sama saja?"},
{n:67,type:"mcq",micro:"Dukungan jangka panjang",q:"Setelah situasi perundungan mereda, dukungan yang tetap penting bagi (mantan) korban:",options:["Terus memeriksa keadaan mereka sesekali & mengingatkan bahwa mereka didukung, karena dampaknya bisa bertahan meski kejadiannya sudah berhenti","Menganggap semuanya selesai & tidak perlu dipikirkan lagi","Terus mengungkit kejadian itu setiap saat"],answer:0,explain:"Pemulihan butuh waktu bahkan setelah kejadiannya berhenti. Dukungan yang hangat (tanpa terus mengungkit) tetap berharga.",hint:"Terus memeriksa keadaan dengan hangat, atau anggap selesai / terus mengungkit?"},
{n:68,type:"tf",micro:"Perundungan bukan bagian normal 'tumbuh dewasa'",q:"Benar atau Salah: Perundungan (siber maupun tatap muka) BUKAN 'bagian normal yang harus dilewati semua anak', melainkan masalah nyata yang layak ditangani serius.",answer:true,explain:"Anggapan 'namanya juga anak-anak' meremehkan dampak nyata perundungan & bisa membuat korban merasa tidak didengar.",hint:"Bukan hal normal yang harus dilewati, atau memang bagian wajar tumbuh dewasa?"},
{n:69,type:"mcq",micro:"Perundungan & tanggung jawab platform vs individu",q:"Selain tanggung jawab individu, platform digital juga punya peran mencegah perundungan lewat...",options:["Menjamin tidak akan pernah ada perundungan di platform mereka","Fitur laporan, moderasi konten, & kebijakan yang jelas, meski tetap tidak bisa mencegah semuanya sendirian","Tidak punya peran sama sekali, semua tanggung jawab pengguna"],answer:1,explain:"Tanggung jawab berbagi: individu bersikap baik, platform menyediakan alat & aturan, meski tidak sempurna sendirian.",hint:"Punya peran lewat fitur & kebijakan, atau sepenuhnya tanggung jawab individu / jaminan sempurna?"},
{n:70,type:"tf",micro:"Membicarakannya membantu pencegahan",q:"Benar atau Salah: Membicarakan topik perundungan siber secara terbuka (di kelas, keluarga) membantu semua orang lebih siap mengenali & menanganinya, bukan membuatnya makin sering terjadi.",answer:true,explain:"Membicarakan secara terbuka membangun kesadaran & kesiapan, bukan 'memberi ide' untuk melakukannya, seperti membicarakan keselamatan lalu lintas tidak membuat orang jadi ugal-ugalan.",hint:"Membantu kesiapan & pencegahan, atau justru membuat makin sering terjadi?"},
{n:71,type:"mcq",micro:"Perundungan menyasar yang berbeda",q:"Orang yang dianggap 'berbeda' (penampilan, cara bicara, minat, latar belakang) kadang lebih rentan jadi sasaran karena...",options:["Menjadi berbeda memang salah & pantas dikomentari","Hanya terjadi pada orang yang benar-benar 'aneh'","Sebagian pelaku memakai perbedaan sebagai alasan untuk menyerang, meski perbedaan itu sendiri bukan kesalahan siapa pun"],answer:2,explain:"Perbedaan bukan alasan sah untuk diserang. Memahami ini penting untuk membangun sikap yang menghargai keberagaman.",hint:"Perbedaan dijadikan alasan menyerang secara tidak adil, atau memang salah / hanya untuk orang 'aneh'?"},
{n:72,type:"mcq",micro:"Menahan diri dari menghakimi tanpa tahu detail",q:"Melihat sepotong percakapan yang terlihat seperti seseorang 'pantas' dirundung (tanpa tahu konteks lengkapnya), sikap yang bijak:",options:["Tidak buru-buru ikut menghakimi atau menyerang; cari tahu konteks lengkap atau tidak ikut campur berdasarkan info sepotong","Langsung ikut menyerang karena 'orang itu pantas'","Percaya sepenuhnya pada potongan yang terlihat tanpa mempertanyakan apa pun"],answer:0,explain:"Konteks sering hilang di potongan percakapan yang beredar. Tidak buru-buru menghakimi mencegah ikut serta dalam ketidakadilan.",hint:"Jangan buru-buru menghakimi tanpa konteks lengkap, atau langsung ikut menyerang?"},
{n:73,type:"mcq",micro:"Perundungan & tanggung jawab kolektif kelas/komunitas",q:"Sebuah kelas/komunitas dengan budaya saling mendukung (bukan saling menjatuhkan) cenderung...",options:["Justru lebih rentan karena dianggap 'lemah'","Memiliki lebih sedikit kasus perundungan & lebih cepat menangani bila ada yang terjadi","Sama saja tingkat perundungannya dengan kelompok lain"],answer:1,explain:"Budaya kolektif yang positif membentuk norma bahwa merundung tidak diterima, membuat pelaku potensial berpikir dua kali & korban lebih berani bicara.",hint:"Lebih sedikit kasus & lebih cepat tertangani, atau sama saja / lebih rentan?"},
{n:74,type:"mcq",micro:"Perundungan & keberanian mengakui kesalahan",q:"Kalau kamu diberi tahu bahwa sesuatu yang kamu lakukan menyakiti seseorang (meski tidak bermaksud begitu), respons yang matang:",options:["Langsung membela diri & menolak mendengarkan","Menyalahkan orang yang memberi tahu karena 'terlalu sensitif'","Dengarkan dengan terbuka, jangan langsung defensif, & pertimbangkan sungguh-sungguh apakah kamu perlu meminta maaf & mengubah perilaku"],answer:2,explain:"Menerima umpan balik dengan terbuka, meski awalnya terasa tidak nyaman, adalah tanda kedewasaan yang mencegah perilaku menyakitkan berulang.",hint:"Dengarkan terbuka & pertimbangkan, atau membela diri / menyalahkan yang memberi tahu?"},
{n:75,type:"order",micro:"Membangun budaya kelas yang anti-perundungan",q:"Urutkan langkah membangun budaya kelas/grup yang mencegah perundungan siber.",items:["Diskusikan bersama apa itu perundungan & kenapa itu merugikan semua orang","Sepakati bersama aturan/norma tentang perilaku yang diterima di grup digital kelas","Dorong semua anggota berani menjadi upstander dengan cara yang aman","Sediakan jalur jelas untuk melapor bila ada masalah, & tindak lanjuti dengan serius"],answer:[0,1,2,3],explain:"Diskusi bersama membangun pemahaman → sepakati norma → dorong keberanian membela → sediakan jalur pelaporan yang ditindaklanjuti. Fondasi pemahaman bersama datang lebih dulu.",hint:"Menyepakati norma bersama sebelum atau sesudah diskusi bersama tentang perundungan?"},
{n:76,type:"tf",micro:"Kesadaran & keberanian bisa dilatih",q:"Benar atau Salah: Kemampuan mengenali perundungan & keberanian menjadi upstander bisa dilatih & tumbuh seiring waktu, bukan sesuatu yang otomatis dimiliki semua orang sejak awal.",answer:true,explain:"Seperti keterampilan lain, latihan (lewat diskusi, contoh, & kesempatan bertindak kecil) menumbuhkan keberanian & kepekaan ini.",hint:"Bisa dilatih & tumbuh, atau otomatis dimiliki semua orang?"},
{n:77,type:"mcq",micro:"Perundungan & jejak digital jangka panjang",q:"Terlibat dalam perundungan (sebagai pelaku) di masa muda bisa berdampak jangka panjang karena...",options:["Rekam jejak digital & reputasi bisa bertahan lama, memengaruhi hubungan & kesempatan di masa depan","Tidak ada dampak jangka panjang sama sekali","Hanya berdampak selama masih di sekolah yang sama"],answer:0,explain:"Sama seperti jejak digital lainnya, keterlibatan dalam perundungan bisa tercatat & ditemukan lagi di kemudian hari.",hint:"Bisa berdampak jangka panjang, atau tak ada dampak / hanya sementara?"},
{n:78,type:"mcq",micro:"Menyeimbangkan tegas & berempati",q:"Menangani perundungan dengan baik berarti bisa...",options:["Selalu memilih untuk tidak tegas demi menjaga hubungan baik","Tegas bahwa perilaku menyakiti tidak diterima, sambil tetap berempati pada semua pihak yang terlibat (termasuk memahami pelaku tanpa membenarkannya)","Hanya bisa memilih salah satu, tegas atau berempati, tidak bisa keduanya"],answer:1,explain:"Ketegasan & empati bisa berjalan bersama: jelas bahwa perilakunya salah, tapi tetap memperlakukan semua pihak sebagai manusia yang bisa berubah/pulih.",hint:"Tegas & berempati bersama, atau harus pilih salah satu / selalu longgar?"},
{n:79,type:"mcq",micro:"Perundungan & harapan untuk berubah",q:"Seseorang yang pernah jadi pelaku perundungan bisa berubah & memperbaiki diri jika...",options:["Tidak pernah bisa berubah sama sekali seumur hidup","Diberi hukuman keras tanpa proses pemahaman apa pun","Diberi kesempatan menyadari kesalahannya, bertanggung jawab, & membangun kebiasaan baru dengan dukungan yang tepat"],answer:2,explain:"Perubahan mungkin terjadi lewat kesadaran, tanggung jawab, & dukungan, bukan sekadar hukuman tanpa proses refleksi.",hint:"Bisa berubah lewat kesadaran & dukungan, atau tak pernah bisa berubah?"},
{n:80,type:"open",micro:"Refleksi diri & memutus siklus",q:"Bayangkan kamu menyadari bahwa selama ini kamu sering ikut menertawakan/membagikan konten yang mengejek seorang teman sekelas, meski tidak pernah menulis komentar jahat sendiri. Tulis: (a) kenapa perilaku ini tetap termasuk 'ikut merundung' meski kamu tidak menulis apa pun, (b) apa yang akan kamu lakukan sekarang setelah menyadarinya, (c) bagaimana kamu akan meminta maaf (bila perlu) dengan cara yang tulus, (d) satu kebiasaan baru yang akan kamu terapkan ke depan.",sample:"(a) Perilaku ini tetap termasuk ikut merundung karena: menertawakan & membagikan konten yang mengejek menambah jangkauan & 'validasi' bagi pelaku utama, membuat korban merasa lebih banyak orang menertawakannya, & partisipasiku (meski pasif) membuat pola itu terus berlanjut karena tidak ada yang menghentikannya, aku ikut jadi bagian dari masalahnya meski tidak memulainya. (b) Yang akan kulakukan sekarang: berhenti sepenuhnya menertawakan/membagikan/memberi reaksi pada konten seperti itu ke depannya, & memikirkan bagaimana aku bisa mendukung temanku yang jadi sasaran, mungkin lewat pesan pribadi yang tulus. (c) Cara meminta maaf yang tulus: aku akan menghubungi temanku secara pribadi (bukan di depan orang lain yang bisa membuatnya makin tidak nyaman), mengakui secara spesifik apa yang kulakukan ('aku sadar aku ikut menertawakan & membagikan waktu itu'), tidak membela diri dengan 'tapi aku kan nggak nulis apa-apa', & menanyakan apakah ada yang bisa kulakukan untuk membantu sekarang. (d) Kebiasaan baru: sebelum menertawakan atau membagikan sesuatu, aku akan bertanya pada diriku 'apakah ini menyakiti seseorang, & bagaimana perasaanku kalau itu terjadi padaku?' sebagai jeda sebelum bertindak.",explain:"Jawaban baik: penjelasan yang jujur & spesifik tentang kenapa partisipasi pasif tetap berdampak, rencana tindakan konkret ke depan, permintaan maaf yang tulus & spesifik (bukan defensif), & kebiasaan baru yang benar-benar bisa diterapkan sebagai jeda sebelum bertindak.",hint:"Bagian (c) jangan sampai terdengar defensif ('kan aku nggak nulis apa-apa'), pengakuan tulus tanpa pembelaan diri jauh lebih bermakna bagi yang menerima maaf."},

// FASE E — TANTANGAN (81-100): skenario & kapstone
{n:81,type:"mcq",micro:"Skenario: grup chat mulai menyerang satu orang",q:"Kamu ada di grup chat kelas & melihat beberapa orang mulai mengejek satu siswa secara bertubi-tubi. Langkah pertama yang aman & membantu:",options:["Kirim pesan pribadi ke siswa yang diejek untuk menunjukkan dukungan, sambil mempertimbangkan memberi tahu wali kelas","Ikut menambahkan komentar supaya tidak dianggap aneh sendiri","Keluar dari grup tanpa melakukan apa pun untuk membantu"],answer:0,explain:"Dukungan pribadi + pertimbangkan melibatkan orang dewasa adalah langkah yang aman & benar-benar membantu, dibanding ikut serta atau lari tanpa bertindak.",hint:"Dukung pribadi & pertimbangkan lapor, atau ikut serta / lari tanpa bertindak?"},
{n:82,type:"mcq",micro:"Skenario: kamu diejek berulang di game daring",q:"Dalam sebuah game daring, pemain lain terus mengejekmu setiap kali bermain bersama selama beberapa minggu. Langkah yang tepat:",options:["Membalas dengan ejekan yang lebih pedas","Blokir/mute pemain itu, laporkan lewat fitur game, & simpan bukti bila diperlukan lebih lanjut","Terus bermain bersama & berharap mereka berhenti sendiri"],answer:1,explain:"Fitur blokir & lapor di game dirancang untuk menangani situasi seperti ini. Menggunakannya adalah langkah proaktif melindungi diri.",hint:"Blokir & lapor, atau terus bermain berharap berhenti / balas lebih pedas?"},
{n:83,type:"mcq",micro:"Skenario: akun palsu meniru temanmu",q:"Kamu menemukan akun palsu yang meniru identitas temanmu untuk mempermalukannya. Langkah yang membantu:",options:["Diam saja karena bukan urusanmu langsung","Membalas akun palsu itu dengan ejekan","Beri tahu temanmu segera, bantu dia melaporkan akun itu ke platform, & simpan bukti tangkapan layar"],answer:2,explain:"Memberi tahu & membantu proses pelaporan menunjukkan solidaritas yang nyata & membantu penanganan resmi.",hint:"Beri tahu & bantu lapor, atau diam / balas dengan ejekan?"},
{n:84,type:"mcq",micro:"Skenario: kamu diminta ikut menyebarkan sesuatu yang menyakiti",q:"Teman mengirimimu sebuah pesan/gambar yang mengejek seseorang & memintamu ikut membagikannya. Sikap yang tepat:",options:["Tolak membagikannya, & sampaikan dengan baik bahwa kamu tidak nyaman ikut serta","Bagikan saja karena 'sudah banyak yang bagikan'","Bagikan diam-diam tanpa komentar apa pun"],answer:0,explain:"Menolak ikut menyebarkan, meski dengan sopan, memutus salah satu mata rantai penyebaran yang menyakiti seseorang.",hint:"Tolak dengan sopan, atau bagikan (dengan/tanpa komentar)?"},
{n:85,type:"tf",micro:"Setiap orang bisa jadi bagian solusi",q:"Benar atau Salah: Setiap orang, tidak peduli seberapa kecil perannya, bisa menjadi bagian dari solusi mengurangi perundungan siber lewat pilihan kecil sehari-hari (tidak ikut menyebar, mendukung korban, dll).",answer:true,explain:"Perubahan budaya digital dibangun dari banyak pilihan kecil individu yang menumpuk jadi dampak besar.",hint:"Bisa jadi bagian solusi lewat pilihan kecil, atau perlu tindakan besar untuk berpengaruh?"},
{n:86,type:"mcq",micro:"Skenario: adikmu jadi korban & takut cerita ke orang tua",q:"Adikmu bercerita dirundung online tapi memohon jangan diberi tahu orang tua karena takut HP-nya disita. Sikap yang bijak:",options:["Langsung memberi tahu orang tua tanpa berbicara dulu dengan adikmu","Dengarkan dulu, yakinkan bahwa ini bukan salahnya, & bantu menemukan cara bercerita ke orang tua bersama-sama, karena bantuan orang dewasa penting","Berjanji tidak akan pernah memberi tahu siapa pun demi menjaga rahasianya"],answer:1,explain:"Menghormati perasaannya sambil tetap mengarahkan ke bantuan orang dewasa (dengan cara yang tidak membuatnya makin takut) adalah keseimbangan yang tepat.",hint:"Dengarkan & bantu bicara ke orang tua bersama, atau berjanji rahasia selamanya / langsung lapor tanpa bicara dulu?"},
{n:87,type:"mcq",micro:"Skenario: kamu tidak yakin sesuatu termasuk perundungan",q:"Kamu ragu apakah sebuah candaan berulang di grup termasuk perundungan atau sekadar bercanda biasa. Cara memastikan:",options:["Anggap selalu bercanda selama kamu sendiri tidak merasa tersinggung","Abaikan keraguanmu & tidak melakukan apa-apa","Perhatikan reaksi orang yang jadi objek candaan, apakah mereka benar-benar nyaman atau hanya berpura-pura tertawa; tanyakan langsung bila perlu"],answer:2,explain:"Reaksi objek candaan (bukan reaksimu sendiri) adalah petunjuk terbaik. Bertanya langsung dengan baik juga bisa memperjelas.",hint:"Perhatikan reaksi objeknya & tanya langsung, atau anggap bercanda karena kamu sendiri tak tersinggung?"},
{n:88,type:"mcq",micro:"Skenario: perundungan menyeberang dari daring ke sekolah",q:"Perundungan yang dimulai secara online mulai berlanjut jadi diabaikan/dikucilkan di sekolah juga. Ini menunjukkan pentingnya...",options:["Menangani perundungan siber & tatap muka secara terintegrasi, karena keduanya bisa saling terkait & memperkuat satu sama lain","Menangani keduanya secara sepenuhnya terpisah tanpa hubungan","Perundungan daring tidak pernah berpengaruh ke kehidupan sekolah"],answer:0,explain:"Batas antara dunia daring & tatap muka semakin tipis bagi banyak siswa. Penanganan yang efektif perlu melihat keduanya sebagai satu kesatuan.",hint:"Tangani secara terintegrasi, atau terpisah total / tak berpengaruh?"},
{n:89,type:"mcq",micro:"Skenario: kamu melihat perundungan di platform yang tidak kamu kenal baik",q:"Kamu melihat perundungan terjadi di sebuah platform/forum yang tidak biasa kamu pakai. Langkah yang tetap bisa membantu:",options:["Ikut berkomentar meski tidak familiar dengan konteksnya","Cari fitur laporan platform itu bila ada, & bila menyangkut orang yang kamu kenal, beri tahu mereka atau orang dewasa yang relevan","Abaikan karena bukan platform yang kamu kenal"],answer:1,explain:"Bahkan di platform yang kurang familiar, langkah dasar (laporkan, beri tahu yang relevan) tetap bisa dilakukan.",hint:"Cari cara melapor & beri tahu yang relevan, atau abaikan / ikut komentar tanpa paham konteks?"},
{n:90,type:"order",micro:"Proyek: kampanye anti-perundungan kelas",q:"Urutkan langkah membuat kampanye kesadaran anti-perundungan siber untuk kelas.",items:["Survei/diskusi kecil untuk memahami pengalaman & kekhawatiran teman-teman sekelas","Rancang pesan/poster yang jelas tentang tanda perundungan & cara menjadi upstander","Sampaikan dengan cara yang mengajak, bukan menggurui (cerita, contoh nyata, diskusi)","Buat kesepakatan bersama kelas & jalur pelaporan yang jelas jika ada masalah"],answer:[0,1,2,3],explain:"Pahami situasi nyata → rancang pesan → sampaikan dengan cara yang mengajak → sepakati aturan & jalur bantuan bersama. Dimulai dari memahami kenyataan kelas sendiri, bukan asumsi.",hint:"Merancang poster sebelum atau sesudah memahami pengalaman nyata teman sekelas?"},
{n:91,type:"mcq",micro:"Skenario: kamu ragu melapor karena takut dianggap 'tukang lapor'",q:"Kamu ingin melapor perundungan yang kamu lihat tapi takut dicap 'tukang lapor' oleh teman-teman. Cara menyikapinya:",options:["Batalkan niat melapor karena takut dicap","Melapor tapi memberi tahu semua orang bahwa kamu yang melapor","Ingat bahwa melindungi seseorang dari perundungan lebih penting daripada khawatir soal label, & laporan bisa dilakukan secara rahasia/pribadi"],answer:2,explain:"Banyak jalur pelaporan bisa dilakukan secara rahasia. Prioritas keselamatan & kesejahteraan seseorang lebih penting daripada kekhawatiran akan label sosial.",hint:"Utamakan melindungi & lapor secara rahasia, atau batalkan / umumkan diri sebagai pelapor?"},
{n:92,type:"tf",micro:"Perundungan adalah masalah bersama",q:"Benar atau Salah: Mengatasi perundungan siber bukan hanya tanggung jawab korban atau pelaku semata, tapi tanggung jawab bersama komunitas (teman, sekolah, keluarga, platform).",answer:true,explain:"Perundungan berkembang dalam konteks sosial. Menanganinya butuh peran semua pihak, tidak bisa dibebankan hanya pada dua orang yang terlibat langsung.",hint:"Tanggung jawab bersama komunitas, atau hanya korban & pelaku?"},
{n:93,type:"mcq",micro:"Skenario: kamu pernah jadi bagian masalah, sekarang ingin membantu",q:"Kamu pernah ikut menertawakan seseorang yang dirundung dulu, & sekarang ingin membantu memperbaiki keadaan. Langkah yang tulus:",options:["Akui masa lalumu dengan jujur ke diri sendiri, minta maaf bila memungkinkan, & mulai bertindak berbeda mulai sekarang, tanpa perlu terus menghukum diri sendiri","Tidak melakukan apa-apa karena merasa 'sudah terlambat & tidak pantas membantu'","Berpura-pura tidak pernah terlibat sama sekali"],answer:0,explain:"Pertumbuhan & perbaikan diri tetap bermakna, kapan pun dimulai. Merasa 'tidak pantas' seharusnya tidak menghalangi niat baik untuk berubah.",hint:"Akui, minta maaf, & mulai berubah, atau merasa terlambat / berpura-pura?"},
{n:94,type:"mcq",micro:"Skenario: perundungan terjadi antara adik-kakak kelas",q:"Kamu (kakak kelas) melihat siswa kelas lebih muda dirundung oleh teman-teman seangkatanmu. Sikap yang tepat:",options:["Ikut serta karena teman-teman seangkatanmu melakukannya","Tetap peduli & bertindak sesuai kemampuanmu (dukung korban, beri tahu guru), meski beda usia/kelas","Anggap bukan urusanmu karena beda angkatan"],answer:1,explain:"Kepedulian & tanggung jawab tidak dibatasi usia/kelas. Melihat sesama siswa disakiti tetap layak direspons dengan peduli.",hint:"Tetap peduli & bertindak, atau anggap bukan urusan / ikut serta?"},
{n:95,type:"tf",micro:"Ada harapan & bisa membaik",q:"Benar atau Salah: Meski perundungan siber adalah masalah nyata & serius, ada banyak cara nyata untuk mencegah, menangani, & memulihkan diri darinya, situasinya bukan tanpa harapan.",answer:true,explain:"Pesan yang penting: masalah ini serius tapi bisa ditangani. Ada langkah konkret & dukungan yang tersedia untuk semua yang terlibat.",hint:"Ada harapan & bisa ditangani, atau tanpa harapan?"},
{n:96,type:"mcq",micro:"Skenario: menjadi teladan bagi yang lebih muda",q:"Adik kelas/adikmu mengamati bagaimana kamu bersikap secara daring. Cara menjadi teladan yang baik:",options:["Bersikap baik hanya saat ada yang mengawasi","Menganggap perilaku daringmu tidak memengaruhi siapa pun","Konsisten bersikap baik & berani secara daring meski tidak ada yang melihat langsung, karena perilakumu bisa jadi contoh nyata bagi mereka"],answer:2,explain:"Anak-anak & remaja belajar dari contoh nyata di sekitar mereka. Konsistensi dalam bersikap baik daring adalah pengajaran tanpa kata-kata yang kuat.",hint:"Konsisten baik meski tak diawasi, atau hanya saat diawasi / anggap tak berpengaruh?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu sudah cukup memahami topik perundungan siber:",options:["Kamu bisa mengenali tanda-tandanya, tahu langkah membantu diri sendiri/orang lain, & berani jadi upstander dengan cara yang aman","Kamu hafal definisinya tapi tetap diam saat menyaksikannya","Kamu menghindari semua interaksi daring untuk menghindari risiko"],answer:0,explain:"Pemahaman sejati terlihat dari kesiapan bertindak (mengenali, membantu, berani dengan aman), bukan sekadar hafalan atau penghindaran total.",hint:"Bisa bertindak nyata, atau hafal tanpa bertindak / menghindar total?"},
{n:98,type:"mcq",micro:"Perundungan & budaya digital yang lebih baik",q:"Komunitas digital yang aktif melawan perundungan (bukan membiarkannya) cenderung menjadi tempat yang...",options:["Justru lebih membosankan tanpa 'drama'","Lebih aman & nyaman bagi semua orang untuk berbagi, belajar, & terhubung","Sama saja kualitasnya dengan komunitas yang membiarkan perundungan"],answer:1,explain:"Ruang digital yang bebas dari perundungan memungkinkan orang berinteraksi dengan lebih terbuka & jujur tanpa rasa takut.",hint:"Lebih aman & nyaman untuk berbagi, atau sama saja / membosankan?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'perundungan siber':",options:["Menghindari internet sepenuhnya agar tidak pernah terlibat","Menganggap semua konflik daring sebagai hal biasa yang tidak perlu ditangani","Kenali tanda perundungan (berulang, sengaja, ketidakseimbangan kekuatan), tahu langkah membantu diri sendiri & orang lain, & berani menjadi bagian solusi dengan cara yang aman"],answer:2,explain:"Kenali pola + tahu langkah membantu + berani jadi bagian solusi. Kombinasi ini membuat kita siap menghadapi & mencegah perundungan.",hint:"Kenali + tahu langkah + berani jadi solusi, atau hindari internet / anggap biasa saja?"},
{n:100,type:"open",micro:"Kapstone: komitmen pribadi melawan perundungan siber",q:"Tulis komitmen pribadimu terkait perundungan siber. Sertakan: (a) 3 tanda yang akan selalu membuatmu waspada bahwa sesuatu sudah jadi perundungan, (b) komitmenmu tentang bagaimana kamu akan bersikap sebagai upstander, (c) langkah yang akan kamu ambil bila kamu sendiri jadi korban, (d) bagaimana kamu akan memperlakukan diri sendiri bila menyadari pernah tanpa sadar ikut merundung, (e) satu kalimat yang ingin kamu sampaikan pada diri sendiri untuk diingat saat menghadapi situasi sulit terkait ini.",sample:"(a) 3 tanda perundungan: (1) Sesuatu terjadi berulang, bukan sekali. (2) Ada kesengajaan menyakiti, bukan kesalahpahaman biasa. (3) Ada ketidakseimbangan kekuatan (kelompok vs satu orang, atau pihak yang jelas lebih berkuasa) sehingga korban sulit membela diri setara. (b) Komitmen sebagai upstander: aku berkomitmen untuk tidak ikut menyebarkan/menyukai/menertawakan konten yang merundung siapa pun, mendukung korban secara pribadi meski tidak selalu berani melawan terbuka, & melapor ke orang dewasa bila situasinya serius, meski itu berarti mengambil risiko dilihat sebagai 'ikut campur'. (c) Langkah bila jadi korban: tidak membalas dengan cara yang sama, segera menyimpan bukti, & cerita ke orang tuaku atau wali kelas yang kupercaya secepat mungkin, tanpa menunggu sampai situasinya sangat parah. (d) Memperlakukan diri sendiri bila menyadari pernah ikut merundung tanpa sadar: aku akan mengakuinya dengan jujur (tanpa membela diri berlebihan), meminta maaf secara tulus & spesifik ke orang yang terdampak, memperbaiki perilaku ke depan, tapi tidak menghukum diriku sendiri secara berlebihan selamanya, karena yang penting adalah perubahan nyata setelahnya, bukan rasa bersalah tanpa henti. (e) Kalimat untuk diri sendiri: 'Diam bukan pilihan yang aman bagi orang lain, tapi aku tidak harus melawan sendirian, ada cara aman untuk membantu, & mencari bantuan adalah kekuatan, bukan kelemahan.'",explain:"Jawaban baik: 3 tanda yang benar & konsisten dengan materi (berulang, sengaja, ketidakseimbangan kekuatan), komitmen upstander yang konkret & realistis (bukan janji heroik yang tidak realistis), langkah korban yang berurutan & benar, sikap yang seimbang terhadap diri sendiri bila pernah ikut merundung (jujur & bertanggung jawab tanpa self-blame berlebihan), & kalimat penutup yang bermakna & personal, bukan slogan generik.",hint:"Bagian (d) penting, tunjukkan keseimbangan antara bertanggung jawab atas kesalahan & tidak menghukum diri secara berlebihan, keduanya penting untuk perubahan yang sehat."},
];
